select throws_ok($q$select public.edit_evalia_product('e2100000-0000-4000-8000-000000000041','QA Original','M',380,array['e2100000-0000-4000-8000-000000000032']::uuid[],null,(select updated_at from public.models where id='e2100000-0000-4000-8000-000000000041'),'e2100000-0000-4000-8000-000000000071')$q$,'23514',null,'pending color cannot be withdrawn');
select throws_ok($q$select public.save_evalia_color('e2100000-0000-4000-8000-000000000031','QA Azul original','#224488',false,(select updated_at from public.colors where id='e2100000-0000-4000-8000-000000000031'),'e2100000-0000-4000-8000-000000000072')$q$,'23514',null,'pending color cannot be disabled globally');
