select lives_ok($q$select public.edit_evalia_product('e2100000-0000-4000-8000-000000000041','QA Corregido','XL',380,array['e2100000-0000-4000-8000-000000000032']::uuid[],null,(select updated_at from public.models where id='e2100000-0000-4000-8000-000000000041'),'e2100000-0000-4000-8000-000000000073')$q$,'edit complete ficha');
