select lives_ok($q$select public.save_evalia_color('e2100000-0000-4000-8000-000000000031','QA Azul corregido','#112233',false,(select updated_at from public.colors where id='e2100000-0000-4000-8000-000000000031'),'e2100000-0000-4000-8000-000000000074')$q$,'inactive historical color can be corrected');
